import{_ as a,o as t,c as n,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Election-chart interpretation conventions","description":"","frontmatter":{},"headers":[],"relativePath":"reference/55-election-chart-interpretation-conventions.md","filePath":"reference/55-election-chart-interpretation-conventions.md","lastUpdated":1789122934000}'),r={name:"reference/55-election-chart-interpretation-conventions.md"};function i(d,e,c,s,l,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="election-chart-interpretation-conventions" tabindex="-1">Election-chart interpretation conventions <a class="header-anchor" href="#election-chart-interpretation-conventions" aria-label="Permalink to &quot;Election-chart interpretation conventions&quot;">​</a></h1><p>This is the canonical policy boundary between source wording and reusable election-chart computation. The machine-readable reference registry is the owner; the generated browser contract is its exact mirror.</p><ul><li>Owner: <code>docs/reference/election-chart-interpretations.json</code></li><li>Browser mirror: <code>src/data/election-chart-interpretations.generated.json</code></li><li>Registry schema: <code>1</code></li><li>Applied-convention schema: <code>2</code> (unchanged)</li><li>Election-rule schema: <code>4</code> (unchanged)</li></ul><p><code>selected</code> means that the repository has fixed a named computational meaning. It does <strong>not</strong> mean the primitive is implemented or wired into an event. An empty <code>implementation</code> list and <code>specified_unwired</code> implementation status preserve that distinction. <code>partial</code> means released code consumes only a documented subset. <code>unresolved</code> forbids automation and ranking effects until a named mode is source-audited, owner-accepted, versioned and tested.</p><h2 id="claim-source-ledger" tabindex="-1">Claim/source ledger <a class="header-anchor" href="#claim-source-ledger" aria-label="Permalink to &quot;Claim/source ledger&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Canonical entry</th><th>Exact source locator</th><th>State</th></tr></thead><tbody><tr><td>Aspect</td><td><code>phaladeepika-full-graha-drishti-v1</code></td><td><em>Phaladeepika</em> II.23, Sastri 1950, book p. 18 / scan p. 55</td><td>Selected and implemented for full classical aspects; partial and node aspects stay separate</td></tr><tr><td>Conjunction</td><td><code>same-rasi-distributive-conjunction-v1</code></td><td>Raman, Chapter X “Borrowing Money,” internal p. 45 / physical PDF p. 49</td><td>Reusable Python/TypeScript primitive implemented with no degree orb; borrowing event effect remains unwired</td></tr><tr><td>Benefic/malefic</td><td><code>phaladeepika-natural-graha-nature-whole-sign-v1</code></td><td><em>Phaladeepika</em> II.27, book pp. 19–20 / scan pp. 56–57; corroborating modern BPHS 3.11 witness</td><td>Selected, partially implemented for Annaprasana; generic Budha and benefic predicates remain #251 work</td></tr><tr><td>Dignity</td><td><code>phaladeepika-rasi-dignity-v1</code></td><td><em>Phaladeepika</em> I.6, book pp. 3–4 / scan pp. 40–41</td><td>Selected, partially implemented for Gold; not a strength score</td></tr><tr><td>Strength</td><td><code>bounded-graha-strength-unresolved-v1</code></td><td>Raman, Chapter XV “Surgical Operations,” internal pp. 64–65 / physical PDF pp. 68–69</td><td>Unresolved; neither dignity alone nor an incomplete Shadbala may be relabelled strength</td></tr><tr><td>Fortification</td><td><code>election-lagna-fortification-unresolved-v1</code></td><td>Raman, Chapter IX marriage, internal pp. 41–42 / physical PDF pp. 45–46; Chapter XIV journey, internal pp. 60–61 / physical PDF pp. 64–65</td><td>Unresolved; no composite fortification score</td></tr><tr><td>Affliction</td><td><code>constituent-affliction-unresolved-v1</code></td><td>Raman, Chapter XV “Surgical Operations,” internal pp. 64–65 / physical PDF pp. 68–69</td><td>Unresolved; eventual output must expose constituent evidence</td></tr><tr><td>Combustion</td><td><code>phaladeepika-kapoor-fixed-elongation-combustion-v1</code></td><td>Kapoor commentary on <em>Phaladeepika</em> II.36, physical/printed pp. 26–27</td><td>Selected for Guru and Shukra exact-chart use; not yet implemented or wired</td></tr><tr><td>Waxing/waning Chandra</td><td><code>raman-180-degree-paksha-v1</code></td><td>Raman, Chapter II “On certain special yogas,” internal p. 4 / physical PDF p. 7</td><td>Selected with a separately disclosed 0.02° precision guard</td></tr><tr><td>Lord relationships</td><td><code>phaladeepika-natural-relationships-v1</code></td><td><em>Phaladeepika</em> II.21–22, book p. 17 / scan p. 54</td><td>Selected, partially implemented for Gold; temporary and compound modes unresolved</td></tr><tr><td>Navamsa</td><td><code>bphs-modality-navamsa-v1</code></td><td>BPHS 6.12</td><td>Selected with a separately disclosed 0.01° internal-boundary guard</td></tr><tr><td>Hemming</td><td><code>lagna-hemming-unresolved-v1</code></td><td>Raman, Chapter IX marriage, internal pp. 41–42 / physical PDF pp. 45–46</td><td>Unresolved; no hidden node, nature, aspect or orb semantics</td></tr><tr><td>Named Yoga</td><td><code>named-election-yoga-patterns-unresolved-v1</code></td><td>Raman, Chapter IX marriage, internal pp. 41–42 / physical PDF pp. 45–46</td><td>Unresolved; every Yoga needs its own source and Boolean pattern</td></tr></tbody></table><p>The authoritative machine-readable source records, artifact identities, verification states and scope caveats are in <code>provenance.json</code>. The table is a review aid, not a second source of truth.</p><h2 id="selected-formulae-and-boundaries" tabindex="-1">Selected formulae and boundaries <a class="header-anchor" href="#selected-formulae-and-boundaries" aria-label="Permalink to &quot;Selected formulae and boundaries&quot;">​</a></h2><h3 id="full-graha-drishti" tabindex="-1">Full Graha Drishti <a class="header-anchor" href="#full-graha-drishti" aria-label="Permalink to &quot;Full Graha Drishti&quot;">​</a></h3><p>Let <code>delta = (target Rasi - source Rasi + 12) mod 12</code>. Every classical graha uses offset <code>6</code>; Kuja additionally uses <code>3, 7</code>, Guru <code>4, 8</code>, and Shani <code>2, 9</code>. The relation is directed. Nodes, conjunction, self and partial aspects do not satisfy this mode.</p><h3 id="same-rasi-distributive-conjunction" tabindex="-1">Same-Rasi distributive conjunction <a class="header-anchor" href="#same-rasi-distributive-conjunction" aria-label="Permalink to &quot;Same-Rasi distributive conjunction&quot;">​</a></h3><p>The Borrowing mode is <code>R(Chandra) = R(Kuja) OR R(Chandra) = R(Shani)</code>. Either equality controls the prohibition. Pass requires both inequalities to resolve. There is no angular orb and this mode is not a global default.</p><p>The Python owner is <code>telugu_panchangam/personal/election_assessors/conjunction.py</code>; the browser mirror is <code>src/scorer/election-assessors/conjunction.ts</code>. Both consume only a strictly admitted, complete nine-graha chart. Missing, malformed, duplicate or conflicting facts return <code>unknown</code>. At one sampled state, either known equality returns <code>fail</code>; both known inequalities return <code>pass</code>.</p><p>The window combiner is also three-valued: a known failure dominates unknown, unknown dominates pass, and an all-pass set is still <code>unknown</code> when an interior Rasi transition is not covered or the chart-request budget is exhausted. The shared synthetic oracle covers both sides of the 360°/0° ingress, empty samples, malformed input and every precedence branch.</p><p>The separately named event policy <code>borrowing-money.same-rasi-conjunction-reject-v1</code> records that a future Borrowing assessor will map a known failure to <code>reject</code>. Its status is <code>specified_unwired</code>: the primitive is not imported by an event evaluator, the existing manual check remains visible, and no score, ordering, completion count or user-facing result changes in this delivery.</p><h3 id="natural-graha-nature" tabindex="-1">Natural graha nature <a class="header-anchor" href="#natural-graha-nature" aria-label="Permalink to &quot;Natural graha nature&quot;">​</a></h3><p>Surya, Kuja, Shani, mean Rahu and mean Ketu are fixed malefics; Guru and Shukra are fixed benefics. Chandra follows <code>raman-180-degree-paksha-v1</code>. Budha becomes malefic only under the selected same-Rasi association policy. Functional lordship is a different, currently unresolved fact.</p><h3 id="exact-chart-combustion" tabindex="-1">Exact-chart combustion <a class="header-anchor" href="#exact-chart-combustion" aria-label="Permalink to &quot;Exact-chart combustion&quot;">​</a></h3><p>For Guru or Shukra, compute the shortest longitude separation from Surya:</p><p><code>delta = abs(((longitude(graha) - longitude(Surya) + 180) mod 360) - 180)</code></p><p>The Kapoor thresholds are Guru <code>11°</code>, direct Shukra <code>10°</code>, and retrograde Shukra <code>8°</code>. Version 1 returns combust below <code>T - 0.02°</code>, clear above <code>T + 0.02°</code>, and unknown inside the guard. This does not reuse the observer/atmosphere-dependent heliacal calendar.</p><h3 id="lunar-phase" tabindex="-1">Lunar phase <a class="header-anchor" href="#lunar-phase" aria-label="Permalink to &quot;Lunar phase&quot;">​</a></h3><p>Let <code>E = (Chandra longitude - Surya longitude) mod 360</code>. Waxing is <code>0.02 &lt; E &lt; 179.98</code>; waning is <code>180.02 &lt; E &lt; 359.98</code>. The guarded cells around conjunction and opposition are unknown because the source does not classify the exact boundaries and the chart contract rounds to two decimals.</p><h3 id="navamsa" tabindex="-1">Navamsa <a class="header-anchor" href="#navamsa" aria-label="Permalink to &quot;Navamsa&quot;">​</a></h3><p>Divide a Rasi into nine parts. Start from that Rasi for movable signs, its ninth for fixed signs, and its fifth for dual signs, then advance by the zero-based division index. A value within <code>0.01°</code> of an internal division boundary is unknown.</p><h2 id="precedence-and-conflicts" tabindex="-1">Precedence and conflicts <a class="header-anchor" href="#precedence-and-conflicts" aria-label="Permalink to &quot;Precedence and conflicts&quot;">​</a></h2><p>Every evaluator remains three-valued: <code>pass</code>, <code>fail</code>, or <code>unknown</code>. A source clause and its computational convention remain separate claim IDs. An event effect (<code>reject</code>, <code>qualify</code>, or <code>prefer</code>) is a third layer and cannot be inferred from either one.</p><p>Unresolved concepts produce no automated result. Selected conventions do not silently absorb their alternatives: full aspects do not absorb partial or node aspects; natural relationships do not absorb temporary ones; same-Rasi association does not imply a degree orb; dignity does not imply complete strength; and one named Yoga cannot authorize another.</p><p>Existing privacy, batching, local Drik/Lahiri Whole Sign projection, mean-node, five-minute Lagna-transition guard and fail-closed exact-chart contracts remain unchanged. Primitive and event tickets must reference these stable registry IDs and may only mark an implementation path after parity and boundary tests pass.</p>',29)])])}const m=a(r,[["render",i]]);export{u as __pageData,m as default};
